#!/usr/bin/env python3
from __future__ import annotations

import importlib.util
import pathlib
import shutil
import subprocess
import tempfile
import unittest
from unittest import mock

MODULE_PATH = pathlib.Path(__file__).with_name("validate-cargo-locks.py")
SPEC = importlib.util.spec_from_file_location("validate_cargo_locks", MODULE_PATH)
assert SPEC and SPEC.loader
cargo_locks = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(cargo_locks)


class CargoLockAuthorityTests(unittest.TestCase):
    def setUp(self) -> None:
        self.tempdir = tempfile.TemporaryDirectory()
        self.root = pathlib.Path(self.tempdir.name)
        self.entry = {"name": "alpha", "path": "alpha"}
        self.project = self.root / "alpha"
        self.project.mkdir()
        (self.project / "Cargo.toml").write_text(
            '[package]\nname = "alpha"\nversion = "0.1.0"\n',
            encoding="utf-8",
        )
        (self.project / "Cargo.lock").write_text(
            "# This file is automatically @generated by Cargo.\nversion = 4\n",
            encoding="utf-8",
        )

    def tearDown(self) -> None:
        self.tempdir.cleanup()

    def test_check_delegates_consistency_to_cargo_resolver(self) -> None:
        completed = subprocess.CompletedProcess(["cargo"], 0, "{}", "")
        with mock.patch.object(cargo_locks.subprocess, "run", return_value=completed) as run:
            cargo_locks.check_subject(self.root, self.entry)

        command = run.call_args.args[0]
        self.assertEqual(command[:3], ["cargo", "metadata", "--locked"])
        self.assertIn("--all-features", command)
        self.assertNotIn("--no-deps", command)
        self.assertIn(str(self.project / "Cargo.toml"), command)
        self.assertEqual(run.call_args.kwargs["cwd"], self.project)

    def test_stale_lock_is_classified_explicitly(self) -> None:
        completed = subprocess.CompletedProcess(
            ["cargo"],
            101,
            "",
            "error: cannot update the lock file because --locked was passed",
        )
        with mock.patch.object(cargo_locks.subprocess, "run", return_value=completed):
            with self.assertRaisesRegex(
                cargo_locks.CargoLockError,
                "Cargo.lock is not resolver-consistent",
            ) as raised:
                cargo_locks.check_subject(self.root, self.entry)

        self.assertIn("Never hand-edit the lockfile", str(raised.exception))
        self.assertIn("cannot update the lock file", str(raised.exception))

    def test_refresh_lets_cargo_mutate_then_rechecks_locked(self) -> None:
        success = subprocess.CompletedProcess(["cargo"], 0, "{}", "")
        with mock.patch.object(
            cargo_locks.subprocess,
            "run",
            side_effect=[success, success],
        ) as run:
            cargo_locks.refresh_subject(self.root, self.entry)

        refresh_command = run.call_args_list[0].args[0]
        verify_command = run.call_args_list[1].args[0]
        self.assertNotIn("--locked", refresh_command)
        self.assertIn("--all-features", refresh_command)
        self.assertNotIn("--no-deps", refresh_command)
        self.assertIn("--locked", verify_command)
        self.assertNotIn("--no-deps", verify_command)

    @unittest.skipUnless(shutil.which("cargo"), "real Cargo is required")
    def test_full_resolution_rejects_stale_direct_edge_and_refreshes(self) -> None:
        src = self.project / "src"
        src.mkdir()
        (src / "lib.rs").write_text("pub fn alpha() {}\n", encoding="utf-8")

        beta = self.root / "beta"
        (beta / "src").mkdir(parents=True)
        (beta / "Cargo.toml").write_text(
            '[package]\nname = "beta"\nversion = "0.1.0"\n',
            encoding="utf-8",
        )
        (beta / "src" / "lib.rs").write_text(
            "pub fn beta() {}\n",
            encoding="utf-8",
        )

        gamma = self.root / "gamma"
        (gamma / "src").mkdir(parents=True)
        (gamma / "Cargo.toml").write_text(
            (
                '[package]\n'
                'name = "gamma"\n'
                'version = "0.1.0"\n\n'
                '[dependencies]\n'
                'beta = { path = "../beta" }\n'
            ),
            encoding="utf-8",
        )
        (gamma / "src" / "lib.rs").write_text(
            "pub fn gamma() { beta::beta(); }\n",
            encoding="utf-8",
        )

        # First generate a valid graph where beta is already present only as a
        # transitive dependency. This mirrors #302: tikv-jemalloc-sys already
        # existed in Cargo.lock before becoming a direct optional dependency.
        (self.project / "Cargo.toml").write_text(
            (
                '[package]\n'
                'name = "alpha"\n'
                'version = "0.1.0"\n\n'
                '[dependencies]\n'
                'gamma = { path = "../gamma" }\n'
            ),
            encoding="utf-8",
        )
        subprocess.run(
            [
                "cargo",
                "generate-lockfile",
                "--manifest-path",
                str(self.project / "Cargo.toml"),
            ],
            cwd=self.project,
            text=True,
            capture_output=True,
            check=True,
        )
        original_lock = (self.project / "Cargo.lock").read_text(encoding="utf-8")
        self.assertIn('name = "beta"', original_lock)
        self.assertIn('"gamma"', original_lock)

        # Add a new direct optional edge to the already-locked beta package.
        # Cargo.lock is intentionally left at the previous root dependency
        # shape, exactly the class of stale metadata that #303 missed.
        (self.project / "Cargo.toml").write_text(
            (
                '[package]\n'
                'name = "alpha"\n'
                'version = "0.1.0"\n\n'
                '[features]\n'
                'default = []\n'
                'telemetry = ["dep:beta"]\n\n'
                '[dependencies]\n'
                'gamma = { path = "../gamma" }\n'
                'beta = { path = "../beta", optional = true }\n'
            ),
            encoding="utf-8",
        )

        # This is the #302/#303 false negative: --no-deps can accept the stale
        # root dependency edge because it does not resolve the complete graph.
        legacy = subprocess.run(
            [
                "cargo",
                "metadata",
                "--locked",
                "--all-features",
                "--format-version",
                "1",
                "--no-deps",
                "--manifest-path",
                str(self.project / "Cargo.toml"),
            ],
            cwd=self.project,
            text=True,
            capture_output=True,
            check=False,
        )
        self.assertEqual(legacy.returncode, 0, legacy.stderr)

        with self.assertRaisesRegex(
            cargo_locks.CargoLockError,
            "Cargo.lock is not resolver-consistent",
        ):
            cargo_locks.check_subject(self.root, self.entry)

        # Refresh lets Cargo rewrite the root dependency edge; the exact same
        # full --locked authority must then accept the graph.
        cargo_locks.refresh_subject(self.root, self.entry)
        cargo_locks.check_subject(self.root, self.entry)

        refreshed_lock = (self.project / "Cargo.lock").read_text(encoding="utf-8")
        self.assertNotEqual(refreshed_lock, original_lock)
        alpha_block = refreshed_lock.split('name = "alpha"', 1)[1].split(
            "[[package]]", 1
        )[0]
        self.assertIn('"beta"', alpha_block)
        self.assertIn('"gamma"', alpha_block)

    def test_missing_lockfile_fails_before_cargo(self) -> None:
        (self.project / "Cargo.lock").unlink()
        with mock.patch.object(cargo_locks.subprocess, "run") as run:
            with self.assertRaisesRegex(cargo_locks.CargoLockError, "Cargo.lock"):
                cargo_locks.check_subject(self.root, self.entry)
        run.assert_not_called()

    def test_canonical_subjects_exclude_reserved_projects(self) -> None:
        registry = {
            "workloads": [{"name": "real", "path": "real"}],
            "fixtures": [{"name": "fixture", "path": "fixture"}],
            "reserved_top_level_cargo_projects": [
                {"path": "reserved", "reason": "not a validation subject"}
            ],
        }
        with mock.patch.object(
            cargo_locks.registry_validator,
            "validate_repository",
            return_value=registry,
        ):
            subjects = cargo_locks.canonical_subjects(self.root)
        self.assertEqual([entry["name"] for entry in subjects], ["real", "fixture"])

    def test_check_all_reports_every_stale_subject(self) -> None:
        beta = {"name": "beta", "path": "beta"}
        beta_dir = self.root / "beta"
        beta_dir.mkdir()
        (beta_dir / "Cargo.toml").write_text(
            '[package]\nname = "beta"\nversion = "0.1.0"\n',
            encoding="utf-8",
        )
        (beta_dir / "Cargo.lock").write_text("version = 4\n", encoding="utf-8")

        stale = subprocess.CompletedProcess(
            ["cargo"],
            101,
            "",
            "error: cannot update the lock file because --locked was passed",
        )
        with mock.patch.object(cargo_locks.subprocess, "run", return_value=stale):
            with self.assertRaises(cargo_locks.CargoLockError) as raised:
                cargo_locks.check_all(self.root, (self.entry, beta))

        message = str(raised.exception)
        self.assertIn("alpha:", message)
        self.assertIn("beta:", message)


if __name__ == "__main__":
    unittest.main()
